import React from 'react';
import './style.css';

const translations = {
  'pt-BR': {
    title: 'Experiência',
    experiences: [
      {
        company: 'Esteio Gestão Agropecuária',
        position: 'Estagiária em Desenvolvimento Mobile',
        type: 'Estágio',
        date: 'Janeiro 2025 - Presente',
        location: 'Viçosa, Minas Gerais, Brasil',
        description: 'Desenvolvimento de aplicativos móveis para agropecuária, focando em soluções práticas para produtores rurais. Implementação de funcionalidades para gestão agropecuária, incluindo análise, desenvolvimento, homologação e testes.'
      },
      {
        company: 'EmComp - Empresa Júnior da Computação',
        position: 'Desenvolvedora Full-Stack',
        type: 'Tempo Integral',
        date: 'Maio de 2023 - Presente',
        location: 'Rio Pomba, Minas Gerais, Brasil',
        description: 'Trabalho voluntário como desenvolvedora <strong>Full-Stack</strong> na EmComp, participando de projetos de desenvolvimento de software e soluções tecnológicas para clientes e parceiros da empresa júnior.'
      }
    ]
  },
  en: {
    title: 'Experience',
    experiences: [
      {
        company: 'Esteio Gestão Agropecuária',
        position: 'Mobile Development Intern',
        type: 'Internship',
        date: 'January 2025 - Present',
        location: 'Viçosa, Minas Gerais, Brazil',
        description: 'Development of mobile apps for agribusiness, focusing on practical solutions for rural producers. Implementation of agribusiness management features, including analysis, development, validation and tests.'
      },
      {
        company: 'EmComp - Computer Science Junior Company',
        position: 'Full-Stack Developer',
        type: 'Full-Time',
        date: 'May 2023 - Present',
        location: 'Rio Pomba, Minas Gerais, Brazil',
        description: 'Volunteer work at EmComp, developing technological solutions for clients and partners of the junior company.'
      }
    ]
  }
};

const Experience = ({ language }) => {
  const translation = translations[language];
  const experience = translation.

  return (
    <section className="experience-section">
      <h2>{translation.title}</h2>
      <ul>
        <li>
          <h3>{translation.company}</h3>
          <p className="position">{translation.position}</p>
          <p>{translation.type}</p>
          <p>{translation.date}</p>
          <p>{translation.location}</p>
          <p dangerouslySetInnerHTML={{ __html: translation.description }} />
        </li>
      </ul>
    </section>
  );
}

export default Experience;
